def count_syllables(word: str) -> int:
    vowels = set("aeiouy")
    cleaned = "".join(c for c in word.lower() if 'a' <= c <= 'z')
    if not cleaned:
        return 0
    vowel_groups = 0
    in_group = False
    for c in cleaned:
        if c in vowels:
            if not in_group:
                vowel_groups += 1
                in_group = True
        else:
            in_group = False
    le_rule = len(cleaned) >= 3 and cleaned.endswith("le") and cleaned[-3] not in vowels
    if le_rule:
        result = vowel_groups
    elif cleaned.endswith("e") and vowel_groups > 1:
        result = vowel_groups - 1
    else:
        result = vowel_groups
    return max(1, result)
