import re


def extract_headings(markdown: str) -> List[Tuple[int, str]]:
    result: List[Tuple[int, str]] = []
    lines = markdown.splitlines()
    in_fence = False
    fence_char = None
    for line in lines:
        stripped_for_fence = line.lstrip(' ')
        leading_spaces = len(line) - len(stripped_for_fence)
        if leading_spaces <= 3 and len(stripped_for_fence) >= 3:
            if stripped_for_fence.startswith('```') or stripped_for_fence.startswith('~~~'):
                current_fence_char = stripped_for_fence[:3]
                if not in_fence:
                    in_fence = True
                    fence_char = current_fence_char
                elif current_fence_char == fence_char:
                    in_fence = False
                    fence_char = None
                continue
        if in_fence:
            continue
        if leading_spaces > 3:
            continue
        after_spaces = line[leading_spaces:]
        if not after_spaces.startswith('#'):
            continue
        hash_count = 0
        for ch in after_spaces:
            if ch == '#':
                hash_count += 1
            else:
                break
        if hash_count < 1 or hash_count > 6:
            continue
        rest = after_spaces[hash_count:]
        if rest == '':
            result.append((hash_count, ''))
            continue
        if rest[0] not in ' \t':
            continue
        title = rest.lstrip(' \t')
        title = title.rstrip()
        # Remove trailing # run if preceded by space
        if re.search(r' +#+$', title):
            title = re.sub(r' +#+$', '', title)
        elif title.endswith('#'):
            i = len(title) - 1
            while i >= 0 and title[i] == '#':
                i -= 1
            if i < 0:
                title = ''
        result.append((hash_count, title))
    return result
